_logger_configured = False

tl = get_telemetry_instance()

def run_remote_cmd(logger, user, host, passwd, cmd, priv_key='id_rsa', run_in_bg=False, timeout=10):
    # type: (Logger, str, str, str, str, str, bool, float) -> Tuple[str, str]
    """
    Run command at remote host and return command stdout and stderr.
    If command was run in background both stdout and stderr will be empty string.
    :param logger: network logger
    :param user: user name
    :param host: host name or host IP address
    :param passwd: user password (use for private key as well)
    :param cmd: command to run at remote host
    :param priv_key: private key filename in user .ssh directory, default id_rsa
    :param run_in_bg: if true command will be run in background, default False
    :param timeout: timeout to acquire ssh connection
    :return: tuple with command output and command errors
    """
    from mock import MagicMock
    logger = logger or MagicMock()
    try:
        with _get_ssh_connection(logger, host, user, passwd, priv_key, timeout=timeout) as ssh:
            if run_in_bg:
                channel = ssh.get_transport().open_session()
                cmd = cmd + ' &'
                channel.exec_command(cmd)
                out, err = '', ''
            else:
                _, sout, serr = ssh.exec_command(cmd)
                out, err = sout.read().strip().decode('utf-8'), serr.read().strip().decode('utf-8')
            logger.debug(msg='Send to: {} command: {}'.format(host, cmd))
        return out, err
    except (ssh_exception.NoValidConnectionsError, ssh_exception.SSHException) as err:
        logger.error('Copying files failed. SSH connection failure.')
        return '', str(err)


@contextmanager
def _get_ssh_connection(logger, host, user, passwd, priv_key='id_rsa', timeout=10):
    # type: (Logger, str, str, str, str, float) -> None
    """
    Context manager for ssh connection.

    :param logger: network logger
    :param host: host name or host IP address
    :param user: user name
    :param passwd: user password (use for private key as well)
    :param priv_key: private key filename in user .ssh directory, default id_rsa
    :param timeout: timeout to acquire ssh connection
    :return: ssh_connection
    """
    ssh = SSHClient()
    ssh.set_missing_host_key_policy(AutoAddPolicy())
    try:
        ssh.connect(hostname=host, username=user, password=passwd,
                    key_filename=path.expanduser('~/.ssh/{}'.format(priv_key)), timeout=timeout)
        yield ssh
    except (ssh_exception.NoValidConnectionsError, ssh_exception.SSHException) as err:
        logger.debug('SSH connection failed, please check IP and/or TL config '
                     '(robotlte/config/<site>/<tl_name>/__init__.py). Error: {}'.format(err))
        raise
    except Exception as e:
        logger.debug('Exception: {}'.format(e))
    finally:
        ssh.close()
        del ssh


def _get_output_of_unix_command(cmd, shell=True):
    # type: (list, bool) -> str
    """
    Return unix command output.
    :param cmd: command to execute as list with separated arguments
    :param shell: whether process should be executed in new shell or not
    :return: full command output
    """
    out = check_output(cmd, shell=shell)
    try:
        out = out.decode('utf-8')
    except Exception:
        # todo: catch ValueError, UnicodeError or UnicodeDecodeError only???
        pass
    return out

def run_process(logger, tts_bin, tts_path, enb, params="", communicate=False, timeout=10):
    # type (logger, str, str, int, str, bool, int) -> Popen
    """
        Create client or server process.
        :param logger:
        :param tts_bin: path to tts bin file
        :param tts_path: path to tts bin directory
        :param enb: enb index
        :param params: additional parameters to command
        :param communicate: flag when function wait for process
        :param timeout: how long function wait for process
        :return: process
        """

    with tl.trace("run_popen_process"):
        cmd = split(tts_bin + params)
        proc = Popen(cmd, stdin=PIPE, stdout=PIPE, stderr=None, cwd=tts_path)

        if communicate:
            try:
                proc.communicate(timeout=timeout)
            except TimeoutExpired:
                tl.update("run_process", 1, {"status": "fail", "process_name": tts_bin})
                logger.debug("TT SERVER cfg timeout for enb {}".format(enb))
                proc.kill()
                proc.communicate()
                raise
        else:
            logger.info("Run process command: {}".format(cmd))

        tl.update("run_process", 1, {"status": "success", "process_name": tts_bin})
        return proc


def kill_process_by_pid(pid, signal_number=9, host_data=None):
    # type: (int, int, Optional[vm_host]) -> None
    """
    Brutal force kill of process. Does nothing if PID <= 1 - no point of trying to kill PID == 1.
    :param pid: PID of process to kill
    :param signal_number: number of signal which should be used to kill process, by default SIGKILL(9)
    :param host_data: host param from where output should be taken. If provided then cmd is executed remotely
    """
    if pid > 1:
        if not host_data:
            kill(pid, signal_number)
        else:
            cmd = 'sudo kill -{} {}'.format(signal_number, pid)
            run_remote_cmd(None, host_data.usr, host_data.addr, host_data.passwd, cmd)


def kill_all_processes_containing_name(logger, process_name, signal_number=9):
    # type: (Logger, str, int) -> None
    """
    All processes with specified name are killed.

    :param logger: network logger
    :param process_name: fragment of process name to be killed
    :param signal_number: number of signal which should be used to kill process, by default SIGKILL(9)
    """

    cmd = ["ps -ef | grep -w {name} | grep -v grep".format(name=process_name)]
    try:
        ps_output = _get_output_of_unix_command(cmd)

        for line_with_process in ps_output.splitlines():
            proc_info = line_with_process.split()
            pid = int(proc_info[1])

            proc_cmd_args = " ".join(proc_info)

            kill_process_by_pid(pid, signal_number)
            logger.debug("Process killed:\nPID: {} INFO: {}".format(pid, proc_cmd_args))

    except CalledProcessError:
        logger.debug("There are no processes which name's includes >{}<. No killing this time.".format(process_name))


def get_filenames_containing_string(logger, _path, pattern='*'):
    # type: (Logger, str, str) -> List[str]
    """
    Search through filenames and return matching ones.
    Asterisk <*> can be used as wildcard.
    Matching hidden files with '.' a dot is disabled.

    :param logger: network logger
    :param _path: to folder with files
    :param pattern: to be searched in filenames
    """
    _slash = '/'
    if not _path.endswith(_slash):
        _path += _slash

    dir_and_file = '{p}{s}'.format(p=_path, s=pattern)
    result = glob(dir_and_file)
    logger.debug('Searching for {} result {}'.format(dir_and_file, result))
    return result


def delete_files(logger, files):
    # type: (Logger, List[str]) -> None
    """
    Delete files.

    :param logger: network logger
    :param files: to be deleted
    """
    if isinstance(files, str):
        files = [files]

    for file_to_del in files:
        try:
            remove(file_to_del)
            logger.debug('File {} removed.'.format(file_to_del))
        except OSError as err:
            logger.warning('Cannot remove file {} due to error: \n{}'.format(file_to_del, err))

def file_exists(fpath):
    # type: (str) -> bool
    """
    Check if file exists.

    :param fpath: path to file
    """
    return path.isfile(fpath)


def copy_file(logger, src, dst):
    # type: (Logger, str, str) -> bool
    """
    Copy file to destination directory. Catch OSError.
    :param logger: network logger
    :param src: path to file
    :param dst: destination path for file
    :return: True if success, False otherwise
    """
    try:
        copy(src, dst)
        logger.debug("Copied file {} to: {}".format(src, dst))
        return True
    except (IOError, OSError) as e:
        logger.error("Cannot copy file {} because of error: {}".format(src, e))
        return False


def change_file_permissions(logger, filename, perm):
    # type: (Logger, str, int) -> None
    """
    Change file permisssions.
    :param logger: network logger
    :param filename: path to file
    :param perm: wanted permissions like 0o755
    """
    try:
        chmod(filename, perm)
        logger.debug("Changed permissions of file: {}".format(filename))
    except OSError as e:
        logger.error("Unable to change permissions of file {} due to error: {}".format(filename, e))
        raise


def _cfg_logger(logger_name, full_path, stream):
    # type: (str, str, bool) -> Logger
    global _logger_configured
    if not _logger_configured:
        _log = getLogger('{}.{}'.format(logger_name, LOCAL_MACHINE))
        handlers = []
        if full_path:
            try:
                # todo: in py27 takes no keyword arguments rsplit(sep='/', maxsplit=1)
                makedirs(full_path.rsplit('/', 1)[0])
                # todo: when only PY3 supported remove and use: makedirs(name=log_dir, exist_ok=True)
            except OSError:
                pass
            handlers.append(FileHandler(full_path, mode='w'))
        if stream:
            handlers.append(StreamHandler())
        for h in handlers:
            h.setFormatter(Formatter(LOG_FORMAT))
            h.setLevel(DEBUG)
            _log.addHandler(h)
        _log.setLevel(DEBUG)
        _logger_configured = True
    else:
        _log = getLogger('{}.{}'.format(logger_name, LOCAL_MACHINE))
    return _log


def get_simple_logger(logger, logger_name=__name__, full_path='', stream=False):
    # type: (Logger, str, str, bool) -> Logger
    """
    Create simple logger with basic file and/or stream handlers.

    :param logger: if configured logger is passed it will be returned
    :param logger_name: logger name
    :param full_path: full path to log file, if not empty FIleHandler will be configured
    :param stream: if True StreamHandler will be configured
    :return: logger instance
    """
    if isinstance(logger, Logger):
        log = logger
    else:
        log = _cfg_logger(logger_name, full_path, stream)
    return log


@contextmanager
def _enb_fsm_access(timeout=30, retry_timeout=30, remote_host=None, remote_ssh_user='ute', remote_ssh_pass='ute'):
    # type: (int, int, str, str, str) -> ute_fsmaccess
    """
    Establish connection to FSM eNB.
    :param timeout: timeout in seconds for single action
    :param retry_timeout: timeout in seconds between retries
    :param remote_host: vm address
    :param remote_ssh_user: vm user
    :param remote_ssh_pass: vm password
    :return: ute_fsmaccess instance already connected to enb
    """
    fsm = ute_fsmaccess()
    try:
        fsm.setup_enb_fsm_access(timeout=timeout, retry_timeout=retry_timeout, remote_host=remote_host,
                                 remote_ssh_user=remote_ssh_user,
                                 remote_ssh_pass=remote_ssh_pass)
        yield fsm
    finally:
        fsm.teardown_enb_fsm_access()


@contextmanager
def _wts_fsm_access(logger, timeout=30, retry_timeout=30):
    # type: (Logger, int, int) -> ute_fsmaccess
    """
    Establish connection to FSM WTS.
    :param logger: network logger
    :param timeout: timeout in seconds for single action
    :param retry_timeout: timeout in seconds between retries
    :return: ute_fsmaccess instance already connected to enb
    """
    fsm = ute_fsmaccess()
    iphy_ip = _check_iphy_trs_ip(logger)
    try:
        fsm.setup_wts_fsm_access(host=iphy_ip, timeout=timeout, retry_timeout=retry_timeout)
        yield fsm
    finally:
        fsm.teardown_wts_fsm_access()


def _get_fsm_access(logger, fsm_type, timeout=30, retry_timeout=30):
    # type: (Logger, str, int, int) -> ute_fsmaccess
    """
    Establish connection to FSM eNB or WTS.
    :param logger: network logger
    :param fsm_type:
    :param timeout:
    :param retry_timeout:
    :return: connection to FSM
    """
    if fsm_type == 'enb':
        return _enb_fsm_access(timeout=timeout, retry_timeout=retry_timeout)
    elif fsm_type in ('iphy', 'cus'):
        return _wts_fsm_access(logger, timeout=timeout, retry_timeout=retry_timeout)
    raise AttributeError("Unsupported FSM type ({}). Supported devices: {}".format(fsm_type, ['enb', 'iphy', 'cus']))


def _get_sw_version(fsm, fsm_type):
    # type: (ute_fsmaccess, str) -> str
    """
    Fetch SW version form eNB or WTS.

    :param fsm: istance of ute_fsmaccess
    :param fsm_type: FSM typ as string
    :return: software version
    """
    if fsm_type == 'enb':
        return fsm.get_enb_sw_version()
    elif fsm_type in ('iphy', 'cus'):
        return fsm.get_wts_sw_version()
    raise AttributeError("Unsupported FSM type ({}). Supported devices: {}".format(fsm_type, ['enb', 'iphy', 'cus']))


def get_fsm_sw_version(logger, fsm_type, timeout=30, retry_timeout=3):
    # type: (Logger, str, int, int) -> str
    """
    Fetch SW version form eNB or WTS.

    :param logger: network logger
    :param fsm_type: type of FSM device (enb/iphy)
    :param timeout: timeout in seconds for single action
    :param retry_timeout: timeout in seconds between retries
    :return: software version
    """
    with _get_fsm_access(logger, fsm_type, timeout, retry_timeout) as fsm:
        try:
            fsm_sw_version = _get_sw_version(fsm, fsm_type)
            return fsm_sw_version
        except Exception as exc:
            logger.error(
                'Cannot determine {}_sw_version. Exception [{}] caught [{}]]'.format(fsm_type, type(exc).__name__, exc))
            raise


def _check_iphy_trs_ip(logger, iphy_count=4):
    # type: (Logger, int) -> Optional[str]
    """
    Checks on which IP IPHY is reachable
    :param logger: network logger
    :param iphy_count: amount of IPHYs possible to check
    :return: pingable IPHY IP address or None
    """
    return _check_iphy_reachable(logger, last_octet=1, iphy_count=iphy_count)


def _ping(host):
    # type: (str) -> bool
    """
    Checks if host is pingable
    :param host:
    :return: True if host is reachable or False if it's not
    """
    param = '-n' if platform.system().lower() == 'windows' else '-c'
    command = ['ping', param, '2', host, '-w', '2']
    return call(command, stdin=PIPE, stdout=PIPE, stderr=PIPE) == 0


def _check_iphy_reachable(logger, last_octet, iphy_count):
    # type: (Logger, int, int) -> Optional[str]
    """
    Checks if IP address related to IPHY is reachable
    :param logger: network logger
    :param last_octet: last octet of IP address which may differ
    :param iphy_count: amount of IPHYs possible to check
    :return: pingable IPHY IP address or None
    """
    for iphy_id in range(iphy_count):
        iphy_ip = '192.168.200.{}'.format(last_octet + iphy_id)
        logger.debug('Trying to ping {}'.format(iphy_ip))
        ret = _ping(iphy_ip)
        if ret:
            logger.info('IPHY is pingable on {}'.format(iphy_ip))
            return iphy_ip
    logger.warning('IPHY is not pingable on any IP of [{}]'.format(['192.168.200.{}'.format(last_octet + x)
                                                                    for x in range(iphy_count)]))
    return None


def cell_is_nbiot(cell_dict):
    # type: (dict) -> bool
    """
    Check if eNb cell is NB/IoT.

    :param cell_dict: Cell data dict fetch with CellMapping
    :return: True when cell has DL but not UL, False otherwise
    """
    return bool(not cell_dict['MACULTTI'] and cell_dict['MACDLTTI'])
